1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.util.Locale;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Derives an owner's {@code identityKey}, the single value all duplicate detection is now
11	 * expressed through: the lower-case hex SHA-256 of
12	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}.
13	 *
14	 * <p>The components are taken from the owner as already canonicalised earlier in the create
15	 * pipeline: the telephone in E.164 form (see {@link TelephoneE164}), the email lower-cased, and the
16	 * surname reduced to its {@link Soundex} code. Because the telephone is part of the key, two members
17	 * of the same household (same {@code soundex(lastName)} and postcode) with different telephones have
18	 * different identity keys; only an exact whole-key match is a duplicate. The computed
19	 * {@code householdId} is deliberately no longer part of the key — duplicate detection is this single
20	 * identity key, and a same-surname/same-postcode owner with a different telephone is a soft match
21	 * (see {@link AssignPossibleDuplicate}), not a hard household duplicate.
22	 */
23	public final class OwnerIdentity {
24	
25	    private OwnerIdentity() {
26	    }
27	
28	    public static String of(Owner owner) {
29	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
30	        String email = (owner.getEmail() == null || owner.getEmail().isBlank())
31	                ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
32	        String soundex = Soundex.of(owner.getLastName());
33	        return sha256hex(telephone + "|" + email + "|" + soundex);
34	    }
35	
36	    private static String sha256hex(String value) {
37	        try {
38	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
39	            StringBuilder sb = new StringBuilder(digest.length * 2);
40	            for (byte b : digest) {
41	                sb.append(String.format("%02x", b));
42	            }
43	            return sb.toString();
44	        }
45	        catch (Exception e) {
46	            throw new RuntimeException(e);
47	        }
48	    }
49	}
