1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HashSet;
7	import java.util.Set;
8	
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.mapper.CheckDigits;
11	import org.springframework.samples.petclinic.mapper.Localities;
12	import org.springframework.samples.petclinic.model.FiscalYears;
13	import org.springframework.samples.petclinic.model.Owner;
14	import org.springframework.samples.petclinic.repository.OwnerRepository;
15	
16	/**
17	 * Assigns the owner's {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>} where
18	 * REGION is the region code derived from the postcode (the shared derivation in
19	 * {@link Localities#region(String, String)}, postcode-range first, city fallback), FY is
20	 * the two-digit fiscal year of the (business-day-adjusted) registrationDate, HASH8 is the
21	 * first eight upper-case hex characters of the SHA-256 digest over the normalized
22	 * telephone concatenated with the last name, and CHK is a single Luhn check digit computed
23	 * over the digits of {@code <REGION><FY><HASH8>}. The telephone is already in its
24	 * normalized E.164 form by this step (see {@link ValidateOwnerFields}).
25	 *
26	 * <p>The base id is a pure function of the owner's identity and registration date, but two
27	 * distinct owners can still hash to the same {@code memberId}. When the computed id
28	 * collides with an existing owner's {@code memberId}, {@code -<n>} is appended with the
29	 * smallest {@code n} of 2 or more that makes it unique. The new owner is not yet saved, so
30	 * it is not among the existing owners scanned here.
31	 */
32	public class AssignMemberId {
33	
34	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
35	        String region = Localities.region(owner.getCity(), owner.getPostcode());
36	        String fy = String.format("%02d", FiscalYears.startYear(owner.getRegistrationDate()) % 100);
37	        String hash8 = sha256Hex8(owner.getTelephone() + owner.getLastName());
38	        String withoutCheck = region + fy + hash8;
39	        String base = withoutCheck + CheckDigits.luhn(withoutCheck);
40	
41	        Set<String> taken = new HashSet<>();
42	        for (Owner existing : ownerRepository.findAll()) {
43	            if (existing.getMemberId() != null) {
44	                taken.add(existing.getMemberId());
45	            }
46	        }
47	
48	        String memberId = base;
49	        for (int n = 2; taken.contains(memberId); n++) {
50	            memberId = base + "-" + n;
51	        }
52	        owner.setMemberId(memberId);
53	    }
54	
55	    /** The first eight upper-case hex characters of the SHA-256 digest of {@code s}. */
56	    private static String sha256Hex8(String s) {
57	        byte[] digest;
58	        try {
59	            digest = MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
60	        }
61	        catch (NoSuchAlgorithmException ex) {
62	            throw new IllegalStateException("SHA-256 not available", ex);
63	        }
64	        StringBuilder sb = new StringBuilder(8);
65	        for (int i = 0; sb.length() < 8; i++) {
66	            sb.append(String.format("%02X", digest[i]));
67	        }
68	        return sb.substring(0, 8);
69	    }
70	}
