1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Immutable structured event recorded on successful owner creation, emitted as JSON on
7	 * the dedicated {@code AUDIT} logger by {@link EmitOwnerCreatedEvent}.
8	 *
9	 * <p>Beyond the human-readable audit line, this is the machine-readable record of the
10	 * create. It carries the owner's <em>primary identifier</em> — the {@code memberId}.
11	 * {@link #primaryIdentifier(Owner)} is the single point that names it.
12	 *
13	 * @param seq             monotonically increasing sequence number across creates
14	 * @param ownerId         the generated owner id
15	 * @param memberId        the owner's primary identifier (see above)
16	 * @param membershipLevel the owner's assigned membership level
17	 * @param event           the event marker, always {@link #OWNER_CREATED}
18	 */
19	public record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
20	        Integer membershipLevel, String event) {
21	
22	    /** Event marker for a successful owner create. */
23	    public static final String OWNER_CREATED = "OWNER_CREATED";
24	
25	    /**
26	     * The owner's primary identifier — the {@code memberId}. The single point the event
27	     * reads the identifier from.
28	     */
29	    public static String primaryIdentifier(Owner owner) {
30	        return owner.getMemberId();
31	    }
32	
33	    /** Builds the event for the given create, stamping the next sequence number. */
34	    public static OwnerCreatedEvent of(long seq, Owner owner) {
35	        return new OwnerCreatedEvent(seq, owner.getId(), primaryIdentifier(owner),
36	                owner.getMembershipLevel(), OWNER_CREATED);
37	    }
38	}
