1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Map;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's canonical locality (region). The postcode range is preferred:
9	 * a postcode within a known region range decides the region and disambiguates cities
10	 * that share a name. Only when the postcode is absent or in no known range does the
11	 * fixed city-to-region table apply. Kept as a plain static helper (not a mapper
12	 * method) so MapStruct does not treat it as an implicit String-to-String mapping method.
13	 */
14	public final class Localities {
15	
16	    /** City -> canonical region; anything not listed derives locality "UNKNOWN". */
17	    private static final Map<String, String> CITY_REGION = Map.of(
18	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
19	
20	    /** Region -> inclusive 4-digit postcode range {low, high}. */
21	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
22	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
23	
24	    /** Region -> IANA timezone name; anything not listed derives a null timezone. */
25	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
26	            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
27	
28	    private Localities() {
29	    }
30	
31	    /** The canonical region for the given city, or "UNKNOWN" when the city is not in the table. */
32	    public static String region(String city) {
33	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
34	    }
35	
36	    /**
37	     * The canonical region. The postcode range is looked up first; if the postcode is
38	     * absent or in no known range, falls back to the city-to-region table. Returns
39	     * "UNKNOWN" when neither resolves.
40	     */
41	    public static String region(String city, String postcode) {
42	        String byPostcode = regionByPostcode(postcode);
43	        if (byPostcode != null) {
44	            return byPostcode;
45	        }
46	        return region(city);
47	    }
48	
49	    /**
50	     * The owner's locality, taken from the REGION component of its
51	     * {@code memberId} ({@code <REGION><FY><HASH8><CHK>}) — so the locality is the same
52	     * identity the memberId is built from. Falls back to the shared
53	     * {@link #region(String, String)} derivation for owners without a memberId.
54	     */
55	    public static String region(Owner owner) {
56	        String fromCode = regionOfCode(owner.getMemberId());
57	        if (fromCode != null) {
58	            return fromCode;
59	        }
60	        return region(owner.getCity(), owner.getPostcode());
61	    }
62	
63	    /**
64	     * The owner's IANA timezone name, derived from its {@link #region(Owner) locality}
65	     * via the fixed region-to-timezone table. Returns null when the region has no known
66	     * timezone (e.g. "UNKNOWN").
67	     */
68	    public static String timezone(Owner owner) {
69	        return REGION_TIMEZONE.get(region(owner));
70	    }
71	
72	    /**
73	     * The REGION prefix of a {@code <REGION><FY><HASH8><CHK>} memberId — the leading run
74	     * of letters before the two-digit fiscal year. Returns null when the memberId is
75	     * absent or has no leading letters.
76	     */
77	    private static String regionOfCode(String memberId) {
78	        if (memberId == null) {
79	            return null;
80	        }
81	        int i = 0;
82	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
83	            i++;
84	        }
85	        return i == 0 ? null : memberId.substring(0, i);
86	    }
87	
88	    /** The region whose postcode range contains the given postcode, or null if none. */
89	    private static String regionByPostcode(String postcode) {
90	        if (postcode == null) {
91	            return null;
92	        }
93	        int code;
94	        try {
95	            code = Integer.parseInt(postcode.trim());
96	        } catch (NumberFormatException ex) {
97	            return null;
98	        }
99	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
100	            int[] range = entry.getValue();
101	            if (code >= range[0] && code <= range[1]) {
102	                return entry.getKey();
103	            }
104	        }
105	        return null;
106	    }
107	}
