3	import org.springframework.samples.petclinic.model.MembershipLevels;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
6	
7	/**
8	 * Derives an owner's marketing segment, formatted {@code <TIER>_<AREA>}. TIER is
9	 * {@code PREMIUM} when the membershipLevel is 3 or more, otherwise {@code STANDARD};
10	 * AREA is {@code METRO} when the locality is a known region (NSW, VIC or QLD),
11	 * otherwise {@code REGIONAL}. Kept as a plain static helper (not a mapper method) so
12	 * MapStruct does not treat it as an implicit mapping method.
13	 */
14	public final class OwnerSegments {
15	
16	    private OwnerSegments() {
17	    }
18	
19	    /** The owner's segment, combining membership tier with locality area. */
20	    public static OwnerDto.OwnerSegmentEnum of(Owner owner) {
21	        int membershipLevel = owner.getMembershipLevel() != null ? owner.getMembershipLevel()
22	                : MembershipLevels.of(owner);
23	        boolean premium = membershipLevel >= 3;
24	        boolean metro = !"UNKNOWN".equals(Localities.region(owner));
25	        String tier = premium ? "PREMIUM" : "STANDARD";
26	        String area = metro ? "METRO" : "REGIONAL";
27	        return OwnerDto.OwnerSegmentEnum.valueOf(tier + "_" + area);
28	    }
29	}
