1	package org.springframework.samples.petclinic.mapper;
2	
3	/**
4	 * Computes the Luhn check digit over the digits contained in a string. Non-digit
5	 * characters are ignored, so it applies directly to the '<REGION><FY><HASH8>' prefix
6	 * of a memberId. Kept as a plain static helper (not a mapper method) so MapStruct does
7	 * not treat it as an implicit mapping method.
8	 */
9	public final class CheckDigits {
10	
11	    private CheckDigits() {
12	    }
13	
14	    /**
15	     * The Luhn check digit (0-9) over the digits contained in {@code s}. Returns null
16	     * when {@code s} is null.
17	     */
18	    public static Integer luhn(String s) {
19	        if (s == null) {
20	            return null;
21	        }
22	        int sum = 0;
23	        boolean dbl = true;
24	        for (int i = s.length() - 1; i >= 0; i--) {
25	            char c = s.charAt(i);
26	            if (c < '0' || c > '9') {
27	                continue;
28	            }
29	            int d = c - '0';
30	            if (dbl) {
31	                d *= 2;
32	                if (d > 9) {
33	                    d -= 9;
34	                }
35	            }
36	            sum += d;
37	            dbl = !dbl;
38	        }
39	        return (10 - (sum % 10)) % 10;
40	    }
41	}
