12	/**
13	 * Emits the immutable structured {@link OwnerCreatedEvent} as JSON on the dedicated
14	 * {@code AUDIT} logger, in addition to the human-readable audit line from
15	 * {@link AuditOwnerCreated}. Runs after {@code save}, so the owner has a generated id.
16	 *
17	 * <p>{@code seq} is a monotonically increasing integer across creates (process-wide).
18	 */
19	public class EmitOwnerCreatedEvent {
20	
21	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
22	
23	    private static final AtomicLong SEQ = new AtomicLong();
24	
25	    private static final JsonMapper JSON = JsonMapper.builder().build();
26	
