1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Assigns the owner's soft-match duplicate signal. A create request that clears the hard duplicate
10	 * check (see {@link EnsureUniqueIdentity}) may still resemble an existing owner: when the new owner
11	 * shares an existing owner's {@code soundex(lastName)} (see {@link Soundex}) and postcode while its
12	 * whole {@code identityKey} (see {@link OwnerIdentity}) differs — typically a different telephone —
13	 * it is still created but flagged with {@code possibleDuplicate} true and {@code possibleDuplicateOf}
14	 * set to that existing owner's id. Otherwise {@code possibleDuplicate} is false and
15	 * {@code possibleDuplicateOf} null.
16	 *
17	 * <p>A matching identity key would already have been rejected as a hard duplicate, so requiring the
18	 * key to differ here simply excludes that (impossible-to-reach) case and keeps the soft match to
19	 * genuinely distinct owners who merely sound like a household member.
20	 *
21	 * <p>A declared household member ({@code sharesHousehold} true) is never flagged: it shares an
22	 * existing member's surname and postcode by design, so it is a known household member rather than a
23	 * suspected duplicate.
24	 *
25	 * <p>Only owners with a postcode participate: a match requires both postcodes to be present and
26	 * equal. When several existing owners match, the earliest (lowest id) is reported. Soft-deleted
27	 * owners are ignored. Runs before {@code save}, so the new owner is not compared against itself.
28	 */
29	public class AssignPossibleDuplicate {
30	
31	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
32	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
33	            owner.setPossibleDuplicate(false);
34	            owner.setPossibleDuplicateOf(null);
35	            return; // a declared household member is not a suspected duplicate
36	        }
37	        String soundex = Soundex.of(owner.getLastName());
38	        String postcode = owner.getPostcode();
39	        String identityKey = OwnerIdentity.of(owner);
40	        Owner match = null;
41	        if (postcode != null && !postcode.isBlank()) {
42	            for (Owner existing : ownerRepository.findAll()) {
43	                if (existing.isDeleted()) {
44	                    continue; // a soft-deleted owner is not a soft-match candidate
45	                }
46	                if (soundex.equals(Soundex.of(existing.getLastName()))
47	                        && postcode.equals(existing.getPostcode())
48	                        && !identityKey.equals(OwnerIdentity.of(existing))) {
49	                    if (match == null || lessThan(existing.getId(), match.getId())) {
50	                        match = existing;
51	                    }
52	                }
53	            }
54	        }
55	        if (match != null) {
56	            owner.setPossibleDuplicate(true);
57	            owner.setPossibleDuplicateOf(match.getId());
58	        }
59	        else {
60	            owner.setPossibleDuplicate(false);
61	            owner.setPossibleDuplicateOf(null);
62	        }
63	    }
64	
65	    private static boolean lessThan(Integer a, Integer b) {
66	        if (a == null) {
67	            return false;
68	        }
69	        if (b == null) {
70	            return true;
71	        }
72	        return a < b;
73	    }
74	}
