3	/**
4	 * Standard American Soundex encoding of a surname: the retained first letter followed by three
5	 * digits derived from the following consonants, so names that sound alike share a code (e.g.
6	 * {@code Robert} and {@code Rupert} both encode to {@code R163}).
7	 *
8	 * <p>Used by the owner identity key (see {@link OwnerIdentity}) and the soft-match check
9	 * ({@link AssignPossibleDuplicate}): duplicate detection keys on {@code soundex(lastName)} rather
10	 * than the exact surname, so a phonetic re-spelling of the same household name still matches.
11	 *
12	 * <p>The encoding: keep only letters and upper-case them; the first letter is retained verbatim;
13	 * each subsequent letter maps to a digit (b,f,p,v→1; c,g,j,k,q,s,x,z→2; d,t→3; l→4; m,n→5; r→6),
14	 * with vowels (a,e,i,o,u,y) coding to 0. Adjacent letters with the same digit collapse to one; a
15	 * separating vowel breaks that collapse, while {@code h} and {@code w} are transparent (they do not
16	 * break it). Zeros are dropped and the result is right-padded with zeros or truncated to length 4.
17	 * An input with no letters encodes to {@code 0000}.
18	 */
19	public final class Soundex {
20	
21	    private Soundex() {
22	    }
23	
24	    public static String of(String value) {
25	        if (value == null) {
26	            return "0000";
27	        }
28	        StringBuilder letters = new StringBuilder();
29	        for (int i = 0; i < value.length(); i++) {
30	            char c = value.charAt(i);
31	            if (Character.isLetter(c)) {
32	                letters.append(Character.toUpperCase(c));
33	            }
34	        }
35	        if (letters.length() == 0) {
36	            return "0000";
37	        }
38	        StringBuilder code = new StringBuilder();
39	        code.append(letters.charAt(0));
40	        char previous = codeOf(letters.charAt(0));
41	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
42	            char c = letters.charAt(i);
43	            if (c == 'H' || c == 'W') {
44	                continue; // transparent: does not break a same-digit collapse
45	            }
46	            char digit = codeOf(c);
47	            if (digit != '0' && digit != previous) {
48	                code.append(digit);
49	            }
50	            previous = digit; // a vowel resets, so a same-digit consonant after it counts again
51	        }
52	        while (code.length() < 4) {
53	            code.append('0');
54	        }
55	        return code.substring(0, 4);
56	    }
57	
58	    private static char codeOf(char c) {
59	        switch (c) {
60	            case 'B': case 'F': case 'P': case 'V':
61	                return '1';
62	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
63	                return '2';
64	            case 'D': case 'T':
65	                return '3';
66	            case 'L':
67	                return '4';
68	            case 'M': case 'N':
69	                return '5';
70	            case 'R':
71	                return '6';
72	            default:
73	                return '0'; // vowels a,e,i,o,u,y (h and w are handled before this)
74	        }
75	    }
76	}
