            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});

    /** Region -> IANA timezone name; anything not listed derives a null timezone. */
    private static final Map<String, String> REGION_TIMEZONE = Map.of(
            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");

    private Localities() {
    }

    /** The canonical region for the given city, or "UNKNOWN" when the city is not in the table. */
    public static String region(String city) {
        return CITY_REGION.getOrDefault(city, "UNKNOWN");
    }

    /**
     * The canonical region. The postcode range is looked up first; if the postcode is
     * absent or in no known range, falls back to the city-to-region table. Returns
     * "UNKNOWN" when neither resolves.
     */
    public static String region(String city, String postcode) {
        String byPostcode = regionByPostcode(postcode);
        if (byPostcode != null) {
            return byPostcode;
        }
        return region(city);
    }

    /**
     * The region code embedded <em>inside</em> the version-2 identifiers: the plain
     * {@link #region(String, String) region code} with the fixed {@link #IDENTITY_VERSION_TAG}
     * mixed in (e.g. "V2NSW"). Because the tag is included, no identifier value produced under
     * version 1 (which used the bare region code) can be produced again. This tagged code is an
     * identity building block only — the user-facing {@code locality} keeps the plain region.
     */
    public static String identityRegion(String city, String postcode) {
        return IDENTITY_VERSION_TAG + region(city, postcode);
    }

    /**
     * The owner's locality — the plain region code derived from its city and postcode via the
     * shared {@link #region(String, String)} derivation (postcode-range first, city fallback).
     * This is deliberately the untagged region: the version-2 identity tag lives only inside the
     * identifiers, never in the user-facing locality.
     */
    public static String region(Owner owner) {
        return region(owner.getCity(), owner.getPostcode());
    }

    /**
     * The owner's IANA timezone name, derived from its {@link #region(Owner) locality}
     * via the fixed region-to-timezone table. Returns null when the region has no known
     * timezone (e.g. "UNKNOWN").
     */
    public static String timezone(Owner owner) {
        return REGION_TIMEZONE.get(region(owner));
    }

    /**
     * The REGION prefix of a {@code <REGION><FY><HASH8><CHK>} memberId — the leading run
     * of letters before the two-digit fiscal year. Returns null when the memberId is
     * absent or has no leading letters.
     */
    private static String regionOfCode(String memberId) {
        if (memberId == null) {
            return null;
        }
        int i = 0;
        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
            i++;
        }
        return i == 0 ? null : memberId.substring(0, i);
    }

    /** The region whose postcode range contains the given postcode, or null if none. */
    private static String regionByPostcode(String postcode) {
        if (postcode == null) {
            return null;
        }
        int code;
        try {
            code = Integer.parseInt(postcode.trim());
        } catch (NumberFormatException ex) {
            return null;
        }
        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
            int[] range = entry.getValue();
            if (code >= range[0] && code <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashSet;
import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.CheckDigits;
import org.springframework.samples.petclinic.mapper.Localities;
import org.springframework.samples.petclinic.model.FiscalYears;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>} where
 * REGION is the region code derived from the postcode (the shared derivation in
 * {@link Localities#region(String, String)}, postcode-range first, city fallback), FY is
 * the two-digit fiscal year of the (business-day-adjusted) registrationDate, HASH8 is the
 * first eight upper-case hex characters of the SHA-256 digest over the normalized
 * telephone concatenated with the last name, and CHK is a single Luhn check digit computed
 * over the digits of {@code <REGION><FY><HASH8>}. The telephone is already in its
 * normalized E.164 form by this step (see {@link ValidateOwnerFields}).
 *
 * <p>The base id is a pure function of the owner's identity and registration date, but two
 * distinct owners can still hash to the same {@code memberId}. When the computed id
 * collides with an existing owner's {@code memberId}, {@code -<n>} is appended with the
 * smallest {@code n} of 2 or more that makes it unique. The new owner is not yet saved, so
 * it is not among the existing owners scanned here.
 */
public class AssignMemberId {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String region = Localities.region(owner.getCity(), owner.getPostcode());
        String fy = String.format("%02d", FiscalYears.startYear(owner.getRegistrationDate()) % 100);
        String hash8 = sha256Hex8(owner.getTelephone() + owner.getLastName());
        String withoutCheck = region + fy + hash8;
        String base = withoutCheck + CheckDigits.luhn(withoutCheck);

        Set<String> taken = new HashSet<>();
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.getMemberId() != null) {
                taken.add(existing.getMemberId());
            }
        }

        String memberId = base;
        for (int n = 2; taken.contains(memberId); n++) {
            memberId = base + "-" + n;
        }
        owner.setMemberId(memberId);
    }

    /** The first eight upper-case hex characters of the SHA-256 digest of {@code s}. */
    private static String sha256Hex8(String s) {
        byte[] digest;
        try {
            digest = MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
        StringBuilder sb = new StringBuilder(8);
        for (int i = 0; sb.length() < 8; i++) {
            sb.append(String.format("%02X", digest[i]));
        }
        return sb.substring(0, 8);
    }
}

